<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$from=$_GET['from']??date('Y-01-01');$to=$_GET['to']??date('Y-m-d');$q=$db->prepare("SELECT COALESCE(SUM(total),0) billed,COALESCE(SUM(CASE WHEN status IN ('paid','partially_paid') THEN amount_paid ELSE 0 END),0) collected,COALESCE(SUM(CASE WHEN status IN ('sent','partially_paid','overdue') THEN balance_due ELSE 0 END),0) receivable FROM invoices WHERE status<>'cancelled' AND issue_date BETWEEN ? AND ?");$q->execute([$from,$to]);$summary=$q->fetch();$x=$db->prepare("SELECT COALESCE(SUM(amount),0) expenses FROM expenses WHERE status='recorded' AND expense_date BETWEEN ? AND ?");$x->execute([$from,$to]);$expenses=(float)$x->fetchColumn();$monthly=$db->prepare("SELECT DATE_FORMAT(issue_date,'%Y-%m') period,COALESCE(SUM(total),0) billed,COALESCE(SUM(amount_paid),0) collected FROM invoices WHERE status<>'cancelled' AND issue_date BETWEEN ? AND ? GROUP BY period ORDER BY period");$monthly->execute([$from,$to]);$months=$monthly->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Financial Reports</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Financial Reports</h1><form class="row g-2 mb-4"><div class="col-md-4"><input class="form-control" type="date" name="from" value="<?=$e($from)"></div><div class="col-md-4"><input class="form-control" type="date" name="to" value="<?=$e($to)"></div><div class="col-md-4"><button class="btn btn-dark w-100">Run Report</button></div></form><div class="row g-3 mb-4"><div class="col-md-3"><div class="card"><div class="card-body"><small>Billed</small><h3><?=number_format((float)$summary['billed'],2)?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Collected</small><h3><?=number_format((float)$summary['collected'],2)?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Receivable</small><h3><?=number_format((float)$summary['receivable'],2)?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Expenses</small><h3><?=number_format($expenses,2)?></h3></div></div></div></div><div class="card"><div class="card-body"><h2 class="h5">Monthly Revenue</h2><table class="table"><thead><tr><th>Period</th><th>Billed</th><th>Collected</th></tr></thead><tbody><?php foreach($months as $m):?><tr><td><?=$e($m['period'])?></td><td><?=number_format((float)$m['billed'],2)?></td><td><?=number_format((float)$m['collected'],2)?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>